-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
	-- Ignore maximize requests from all apps. You'll probably like this.
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
	-- Fix some dragging issues with XWayland
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})

hl.window_rule({
	match = {
		class = "deadlock",
	},
	immediate = true,
})

hl.window_rule({
	name = "zen-opacity",
	opacity = "1 0.7",
	match = {
		class = "^(zen|zen-alpha|zen-browser)$",
	},
})

hl.layer_rule({
	name = "recording-setup-blur",
	match = { namespace = "recording-setup" },
	blur = true,
	ignore_alpha = 0,
})

hl.layer_rule({
	name = "launcher-blur",
	match = { namespace = "launcher" },
	blur = true,
	ignore_alpha = 0,
})

hl.layer_rule({
	name = "shortcuts-blur",
	match = { namespace = "shortcuts" },
	blur = true,
	ignore_alpha = 0,
})

-- The frozen screenshot frame must appear and disappear instantly: a layer
-- fade would briefly reveal the live screen and delay the slurp selection.
hl.layer_rule({
	name = "screenshot-no-anim",
	match = { namespace = "screenshot" },
	no_anim = true,
})

